<script setup lang="ts">
import type {PublicProduct} from '@kuaixie/sdk';
import {t,formatAmount,formatDate} from '@kuaixie/i18n';
import {useProductCheckout} from '@kuaixie/ui/useProductCheckout';
import {api} from '../api/client';
import {uniEventValue} from '../utils/uniEvent';
import AddressSelectionMobile from './AddressSelectionMobile.vue';
import InsuranceSelectionMobile from './InsuranceSelectionMobile.vue';
const props=defineProps<{product:PublicProduct}>();const p=useProductCheckout(api,()=>props.product,async(title,content)=>!!(await uni.showModal({title,content})).confirm);
function openCreated(){const result=p.created.value;if(result)uni.navigateTo({url:'/pages/order-detail/index?id='+encodeURIComponent(result.id)})}
function pickTrip(event:unknown){if(!p.pending.value&&!p.busy.value)p.form.tripId=p.trips.value[Number(uniEventValue(event))]?.id||''}
function pickInsurance(event:unknown){if(!p.pending.value&&!p.busy.value)p.form.insuranceChoice=Number(uniEventValue(event))===1?'yes':'waived'}
</script>
<template><view class="checkout-mobile"><view class="op-title">{{t('checkout.title')}}</view><view class="v15-notice">{{t('checkout.boundary')}}</view><view v-if="p.error.value" class="op-error">{{p.error.value}}</view><view v-if="p.created.value" class="op-card"><text>{{t('checkout.created')}}</text><text selectable>{{p.created.value.id}}</text><button @click="openCreated">{{t('account.myOrders')}}</button></view><template v-else><view class="op-card"><text>{{t('checkout.trip')}}</text><picker :disabled="p.busy.value||!!p.pending.value" :value="Math.max(0,p.trips.value.findIndex(trip=>trip.id===p.form.tripId))" :range="p.trips.value.map(trip=>trip.destination+' · '+formatDate(trip.depart_date)+' · '+trip.remaining_slots)" @change="pickTrip"><view class="v15-selector">{{p.trips.value.find(trip=>trip.id===p.form.tripId)?.destination||t('checkout.chooseTrip')}} ⌄</view></picker><text v-if="!p.loading.value&&!p.trips.value.length">{{t('checkout.noTrips')}}</text><button :disabled="p.loading.value||!!p.pending.value" @click="p.loadTrips()">{{t('common.retry')}}</button><button v-if="p.more.value" :disabled="p.loading.value||!!p.pending.value" @click="p.loadTrips(true)">{{t('account.more')}}</button><text>{{t('checkout.quantity')}}</text><input v-model="p.form.quantity" type="number" :disabled="p.busy.value||!!p.pending.value" maxlength="3" class="v15-field"/><AddressSelectionMobile v-if="!p.pending.value&&!p.busy.value" @selected="p.setAddress"/><text>{{t('checkout.contactName')}}</text><input v-model="p.form.contactName" maxlength="64" :disabled="p.busy.value||!!p.pending.value" class="v15-field"/><text>{{t('checkout.contactPhone')}}</text><input v-model="p.form.contactPhone" maxlength="24" :disabled="p.busy.value||!!p.pending.value" class="v15-field"/><text>{{t('checkout.address')}}</text><textarea v-model="p.form.address" maxlength="512" :disabled="p.busy.value||!!p.pending.value" class="v15-area"/><text>{{t('checkout.expectDate')}}</text><input v-model="p.form.expectDate" maxlength="10" placeholder="YYYY-MM-DD" :disabled="p.busy.value||!!p.pending.value" class="v15-field"/><text>{{t('checkout.note')}}</text><textarea v-model="p.form.note" maxlength="1024" :disabled="p.busy.value||!!p.pending.value" class="v15-area"/><picker :disabled="p.busy.value||!!p.pending.value" :value="p.form.insuranceChoice==='yes'?1:0" :range="[t('checkout.waiveInsurance'),t('checkout.chooseInsurance')]" @change="pickInsurance"><view class="v15-selector">{{t(p.form.insuranceChoice==='yes'?'checkout.chooseInsurance':'checkout.waiveInsurance')}} ⌄</view></picker><InsuranceSelectionMobile v-if="p.form.insuranceChoice==='yes'&&p.form.tripId&&!p.pending.value" subject-type="trip" :subject-id="p.form.tripId" :item-name="product.name" :declared-value="p.declaredValue.value" @selected="p.setInsurance"/><button :disabled="p.busy.value||!!p.pending.value||!p.form.tripId" @click="p.prepare()">{{t('checkout.quote')}}</button></view><view v-if="p.quote.value" class="op-card"><view class="op-card-title">{{t('checkout.quote')}}</view><view class="op-row"><text>{{t('checkout.unitPrice')}}</text><text>{{formatAmount(p.quote.value.unitPrice,'CNY')}}</text></view><view class="op-row"><text>{{t('checkout.goods')}}</text><text>{{formatAmount(p.quote.value.goodsAmount,'CNY')}}</text></view><view class="op-row"><text>{{t('checkout.serviceFee')}}</text><text>{{formatAmount(p.quote.value.serviceFee,'CNY')}}</text></view><view class="op-row"><text>{{t('checkout.escrow')}}</text><text>{{formatAmount(p.quote.value.buyerEscrow,'CNY')}}</text></view><view class="v15-notice">{{t('checkout.insuranceDirect')}}</view><view>{{t('checkout.intentWindow',{hours:p.quote.value.intentHours})}}</view><button :disabled="p.busy.value||!!p.pending.value" @click="p.submit()">{{t('checkout.confirmTitle')}}</button></view><view v-if="p.pending.value" class="op-error">{{t('checkout.unconfirmed')}}</view><button v-if="p.pending.value" :disabled="p.busy.value" @click="p.submit()">{{t('case.retryPending')}}</button><button @click="uni.navigateTo({url:'/pages/buyer-verify/index'})">{{t('checkout.verifyBuyer')}}</button></template></view></template>
<style scoped>.checkout-mobile{margin-top:24rpx;border-top:1rpx solid #cbd5e1;padding-top:24rpx}.checkout-mobile text{display:block;margin:8rpx 0}.checkout-mobile textarea{width:100%;box-sizing:border-box}.checkout-mobile button{margin:16rpx 0}</style>
